import sys
sys.setrecursionlimit(1 << 25)

class _Edge:
    __slots__ = ("to", "rev", "cap")
    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

def max_flow(n, edges, s, t):
    g = [[] for _ in range(n)]
    def add_edge(fr, to, cap):
        forward = _Edge(to, len(g[to]), cap)
        backward = _Edge(fr, len(g[fr]), 0)
        g[fr].append(forward)
        g[to].append(backward)

    for u, v, c in edges:
        add_edge(u, v, c)

    flow = 0
    INF = 10 ** 18
    level = [0] * n
    it = [0] * n

    from collections import deque

    def bfs():
        for i in range(n):
            level[i] = -1
        q = deque()
        level[s] = 0
        q.append(s)
        while q:
            v = q.popleft()
            for e in g[v]:
                if e.cap > 0 and level[e.to] < 0:
                    level[e.to] = level[v] + 1
                    q.append(e.to)
        return level[t] >= 0

    def dfs(v, upTo):
        if v == t:
            return upTo
        for i in range(it[v], len(g[v])):
            e = g[v][i]
            if e.cap > 0 and level[v] < level[e.to]:
                d = dfs(e.to, min(upTo, e.cap))
                if d > 0:
                    e.cap -= d
                    g[e.to][e.rev].cap += d
                    return d
            it[v] += 1
        return 0

    while bfs():
        for i in range(n):
            it[i] = 0
        while True:
            pushed = dfs(s, INF)
            if not pushed:
                break
            flow += pushed
    return flow
