import sys
from collections import deque

sys.setrecursionlimit(10 ** 6)


def max_flow(n, edges, s, t):
    # adjacency list: each edge is [to, rev, capacity]
    graph = [[] for _ in range(n)]
    for u, v, cap in edges:
        graph[u].append([v, len(graph[v]), cap])
        graph[v].append([u, len(graph[u]) - 1, 0])

    INF = 10 ** 18
    flow = 0
    level = [0] * n
    it = [0] * n  # current edge pointer for each vertex

    def bfs():
        for i in range(n):
            level[i] = -1
        q = deque()
        level[s] = 0
        q.append(s)
        while q:
            v = q.popleft()
            for to, rev, cap in graph[v]:
                if cap > 0 and level[to] < 0:
                    level[to] = level[v] + 1
                    q.append(to)
        return level[t] >= 0

    def dfs(v, f):
        if v == t:
            return f
        for i in range(it[v], len(graph[v])):
            it[v] = i
            to, rev, cap = graph[v][i]
            if cap > 0 and level[v] + 1 == level[to]:
                ret = dfs(to, min(f, cap))
                if ret:
                    graph[v][i][2] -= ret
                    graph[to][rev][2] += ret
                    return ret
        return 0

    while bfs():
        # reset edge pointers
        for i in range(n):
            it[i] = 0
        while True:
            pushed = dfs(s, INF)
            if not pushed:
                break
            flow += pushed

    return flow
