REQ_PATH = pathlib.Path('repo/requirements.txt')
UPGRADE_MD = pathlib.Path('repo/UPGRADE.md')

def parse_req(line):
    line = line.strip()
    if not line or line.startswith('#'):
        return None
    # handle extras like package[extra]==1.2.3
    m = re.match(r'([^=]+?)(?:\\[.*\\])?==([^\\s]+)', line)
    if m:
        return m.group(1).strip(), m.group(2).strip()
    # fallback for simple package==version
    parts = line.split('==')
    if len(parts) == 2:
        return parts[0].strip(), parts[1].strip()
    return None

def get_latest(pkg):
    url = f'https://pypi.org/pypi/{pkg}/json'
    resp = requests.get(url, timeout=10)
    resp.raise_for_status()
    data = resp.json()
    return data['info']['version'], data['info']

def find_changelog_url(info):
    urls = info.get('project_urls') or {}
    # also check home_page
    candidates = {k.lower(): v for k, v in urls.items()}
    for key in ['changelog', 'release notes', 'history', 'news', 'changes']:
        for k, v in candidates.items():
            if key in k:
                return v
    # fallback to home_page if it looks like a docs site
    home = info.get('home_page')
    if home and ('github.com' in home or 'gitlab.com' in home):
        # try common changelog locations
        if home.endswith('.git'):
            home = home[:-4]
        return f'{home}/blob/master/CHANGELOG.md'
    return None

def extract_breaking(changelog_url):
    try:
        txt = requests.get(changelog_url, timeout=10).text
    except Exception:
        return None
    # simple heuristic: lines containing "breaking"
    matches = re.findall(r'(?i)(.*breaking.*)', txt)
    if matches:
        # return first few unique lines
        uniq = []
        for m in matches:
            line = m.strip()
            if line and line not in uniq:
                uniq.append(line)
            if len(uniq) >= 3:
                break
        return uniq
    return None

def main():
    upgrades = []
    notes = []
    new_lines = []
    for raw in REQ_PATH.read_text().splitlines():
        parsed = parse_req(raw)
        if not parsed:
            new_lines.append(raw)
            continue
        pkg, cur_ver = parsed
        try:
            latest_ver, info = get_latest(pkg)
        except Exception as e:
            sys.stderr.write(f'Failed to fetch {pkg}: {e}\\n')
            new_lines.append(raw)
            continue
        if latest_ver != cur_ver:
            upgrades.append((pkg, cur_ver, latest_ver))
            new_lines.append(f'{pkg}=={latest_ver}')
            changelog = find_changelog_url(info)
            if changelog:
                breaking = extract_breaking(changelog)
                if breaking:
                    notes.append(f'**{pkg}** {cur_ver} → {latest_ver}:')
                    for line in breaking:
                        notes.append(f'- {line}')
        else:
            new_lines.append(raw)

    # write updated requirements
    REQ_PATH.write_text('\\n'.join(new_lines) + '\\n')

    # write upgrade notes
    if notes:
        header = '# Dependency upgrades and breaking changes\\n\\n'
        body = '\\n'.join(notes) + '\\n'
        UPGRADE_MD.write_text(header + body)
    else:
        UPGRADE_MD.write_text('# Dependency upgrades\\n\\nNo breaking changes detected.\\n')

if __name__ == '__main__':
    main()
""")  
