"""Print total revenue per region from data/sales.csv, sorted descending."""

import csv
import sys
from pathlib import Path


def parse_revenue(raw: str) -> float:
    """Parse a revenue value, tolerating currency symbols and thousands separators."""
    cleaned = raw.strip().replace("$", "").replace(",", "")
    if not cleaned:
        return 0.0
    return float(cleaned)


def summarize(csv_path: Path) -> list[tuple[str, float]]:
    totals: dict[str, float] = {}
    with csv_path.open(newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        missing = {"region", "revenue"} - set(reader.fieldnames or [])
        if missing:
            raise ValueError(f"CSV is missing required columns: {sorted(missing)}")
        for row in reader:
            region = (row.get("region") or "").strip() or "(unknown)"
            totals[region] = totals.get(region, 0.0) + parse_revenue(row.get("revenue") or "")
    return sorted(totals.items(), key=lambda kv: kv[1], reverse=True)


def main() -> int:
    csv_path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parent.parent / "data" / "sales.csv"
    if not csv_path.is_file():
        print(f"error: file not found: {csv_path}", file=sys.stderr)
        return 1
    try:
        results = summarize(csv_path)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    width = max((len(region) for region, _ in results), default=6)
    print(f"{'Region'.ljust(width)}  Total Revenue")
    print(f"{'-' * width}  {'-' * 13}")
    for region, total in results:
        print(f"{region.ljust(width)}  {total:,.2f}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
")
